// Some portions generated by Claude

// Plan task M5.2 (mockup 06): Types and Graphs list first, then fill in counts loaded with counts=true.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { FakeDocument } = require('./browser-fakes.js');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');

const scripts = process.env.WORKBENCH_SCRIPT_DIR
    || path.resolve(__dirname, '../../tools/workbench/src/main/webapp/scripts');

const context = { basePath: '/rdf4j-workbench', repositoryId: 'a', workbench: {} };
const iri = value => ({ kind: 'iri', value });
const integer = value => ({ kind: 'literal', value: String(value), datatype: 'http://www.w3.org/2001/XMLSchema#integer' });

function loadWorkbench() {
    const workbench = {};
    const window = { location: { href: 'http://localhost/rdf4j-workbench/repositories/a/types?filter=Thing' } };
    installDetailDisclosureTemplateRuntime(workbench);
    const sandbox = vm.createContext({ console, URL, Promise, window, workbench, setTimeout });
    for (const filename of ['workbenchViews.js', 'workbenchRoutes.js', 'queryStream.js', 'workbenchApp.js']) {
        vm.runInContext(fs.readFileSync(path.join(scripts, filename), 'utf8'), sandbox, { filename });
    }
    window.workbench = sandbox.workbench;
    window.fetch = () => Promise.reject(new Error('fetch is stubbed through loadModel'));
    return { workbench: sandbox.workbench, window };
}

function flatten(template) {
    if (Array.isArray(template)) {
        return template.map(flatten).join('');
    }
    if (template && Array.isArray(template.strings)) {
        return template.strings.reduce((result, fragment, index) => result + fragment
            + (index < template.values.length ? flatten(template.values[index]) : ''), '');
    }
    if (template && template.tagName) {
        return `<${template.tagName.toLowerCase()}>${flatten(template.template)}</${template.tagName.toLowerCase()}>`;
    }
    return template === null || typeof template === 'undefined' ? '' : String(template);
}

function harness(window, model) {
    const document = new FakeDocument();
    const mount = document.createElement('main');
    const listeners = new Map();
    window.innerHeight = 600;
    window.scrollY = 0;
    window.addEventListener = (name, listener) => listeners.set(name, listener);
    window.removeEventListener = name => listeners.delete(name);
    const geometry = document.createElement('table');
    geometry.getBoundingClientRect = () => ({ top: 0, height: model.rowCount * 44 });
    const originalQuery = mount.querySelectorAll.bind(mount);
    mount.querySelectorAll = selector => selector.includes('data-workbench-row-table') ? [geometry] : originalQuery(selector);
    const renderer = {
        nothing: '',
        html(strings, ...values) { return { strings: Array.from(strings), values }; },
        render(template, target) { target.template = template; }
    };
    return { mount, renderer, geometry, listeners };
}

/** The page markup with the separately rendered table body filled in. */
function markup(workbench, mount) {
    const outlet = workbench.views.outletOf ? workbench.views.outletOf(mount) : null;
    return flatten(outlet && outlet.template ? outlet.template : mount.template);
}

function listModel(viewId, vars, rows, metadata = {}) {
    return {
        viewId,
        vars,
        rows: [],
        rowStart: 0,
        rowCount: rows.length,
        rowTopSpacer: 0,
        rowBottomSpacer: 0,
        rowStore: { disposed: false, read: async (start, count) => rows.slice(start, start + count),
            dispose() { this.disposed = true; return Promise.resolve(); } },
        namespaceMap: { 'ex:': 'urn:ex:' },
        links: [],
        metadata
    };
}

async function mounted(workbench, window, model) {
    const page = harness(window, model);
    workbench.views.render(page.mount, model, context, page.renderer);
    const dispose = await workbench.views.bindRowWindows(page.mount, model, context, page.renderer);
    return { ...page, dispose };
}

const settle = () => new Promise(resolve => setImmediate(resolve));

/** The text of every count cell in the markup. */
function countCells(page) {
    return Array.from(page.matchAll(/class="workbench-count-cell"[^>]*>([\s\S]*?)<\/td>/g),
        match => match[1].replace(/<[^>]*>/g, '').trim());
}

test('Types list in name order with pending counts, then re-sort by the counts that arrive', async () => {
    const { workbench, window } = loadWorkbench();
    let release;
    const requested = [];
    workbench.app.loadModel = (_fetcher, url) => {
        requested.push(url);
        return new Promise(resolve => { release = resolve; });
    };
    const model = listModel('types', ['type'], [[iri('urn:ex:Offer')], [iri('urn:ex:Thing')]], { filter: 'Thing' });
    const listStore = model.rowStore;
    const { mount, dispose } = await mounted(workbench, window, model);

    let page = markup(workbench, mount);
    assert.match(page, /<h2>Types<\/h2>/);
    assert.match(page, /id="types-filter"[^>]*name="filter"/);
    assert.match(page, /Instances/);
    assert.match(page, /ex:Offer/, 'types show prefixed names');
    assert.deepEqual(countCells(page), ['…', '…'], 'counts are pending');
    assert.equal(requested.length, 1);
    const url = new URL(requested[0]);
    assert.equal(url.searchParams.get('counts'), 'true');
    assert.equal(url.searchParams.get('filter'), 'Thing', 'the counts keep the filter');

    const countRows = [[iri('urn:ex:Thing'), integer(7)], [iri('urn:ex:Offer'), integer(2)]];
    release(listModel('types', ['type', 'instances'], countRows));
    await settle();
    await settle();
    page = markup(workbench, mount);
    assert.ok(page.indexOf('ex:Thing') < page.indexOf('ex:Offer'), 'rows follow the count order');
    assert.match(page, /aria-sort="descending"[^>]*>Instances/);
    assert.deepEqual(countCells(page), ['7', '2']);
    assert.equal(listStore.disposed, true, 'the name-ordered store is released');
    dispose();
});

test('Types show a dash when counting timed out or failed', async () => {
    for (const outcome of ['timed-out', 'failed']) {
        const { workbench, window } = loadWorkbench();
        workbench.app.loadModel = () => outcome === 'failed' ? Promise.reject(new Error('offline'))
            : Promise.resolve(listModel('types', ['type', 'instances'], [], { 'counts-timed-out': true }));
        const model = listModel('types', ['type'], [[iri('urn:ex:Offer')]]);
        const { mount, dispose } = await mounted(workbench, window, model);
        await settle();
        await settle();
        const page = markup(workbench, mount);
        assert.deepEqual(countCells(page), ['—'], outcome + ' counts show a dash');
        dispose();
    }
});

test('a scroll made while the list rows are being bound moves the row window without another scroll', async () => {
    const { workbench, window } = loadWorkbench();
    workbench.app.loadModel = () => new Promise(() => {});
    const model = listModel('contexts', ['context'],
        Array.from({ length: 400 }, (_unused, index) => [iri('urn:ex:g' + index)]));
    const page = harness(window, model);
    let top = 0;
    page.geometry.getBoundingClientRect = () => ({ top, height: model.rowCount * 44 });
    const read = model.rowStore.read;
    let reads = 0;
    model.rowStore.read = (start, count) => {
        reads++;
        if (reads === 2) {
            // The reader scrolls to the end while the first painted window is read, before scrolling is watched.
            top = -(model.rowCount * 44 - window.innerHeight);
        }
        return read(start, count);
    };
    workbench.views.render(page.mount, model, context, page.renderer);
    const dispose = await workbench.views.bindRowWindows(page.mount, model, context, page.renderer);
    await settle();

    assert.ok(page.listeners.has('scroll'), 'the window follows later scrolling');
    assert.ok(model.rowStart > 300, `the row window shows the scrolled-to rows, not those from ${model.rowStart}`);
    dispose();
});

test('Graphs fill in statements, end with the default graph and offer Explore and Clear', async () => {
    const { workbench, window } = loadWorkbench();
    workbench.app.loadModel = () => Promise.resolve(listModel('contexts', ['context', 'statements'], [
        [iri('urn:ex:g1'), integer(40331)], [iri('urn:ex:g2'), integer(3354)], [null, integer(0)]
    ]));
    const model = listModel('contexts', ['context'], [[iri('urn:ex:g1')], [iri('urn:ex:g2')]]);
    const { mount, dispose } = await mounted(workbench, window, model);
    await settle();
    await settle();
    const page = markup(workbench, mount);
    assert.match(page, /<h2>Graphs<\/h2>/);
    assert.match(page, /workbench-browse-card__count[^>]*>2</);
    assert.deepEqual(countCells(page), ['40331', '3354', '0']);
    assert.ok(page.lastIndexOf('Default graph') > page.lastIndexOf('urn:ex:g2'), 'the default graph is last');
    assert.match(page, /href="clear\?context=%3Curn%3Aex%3Ag1%3E"/);
    assert.match(page, /href="explore\?resource=%3Curn%3Aex%3Ag1%3E"/);
    assert.match(page, /aria-label="Clear graph urn:ex:g1…"/);
    dispose();
});
